        } else if ("BUY3PAY2".equals(coupon)) {
            discount = calculateBuy3Pay2Discount(items, products);
        }

        BigDecimal maxDiscount = CurrencyUtils.multiply(productsSubtotal, COUPON_MAX_PERCENT);
        if (discount.compareTo(maxDiscount) > 0) {
