            throw new OrderServiceException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND);
        }

        return mapOrderToResponse(orderOpt.get());
    }

    private List<Product> getProductsForOrder(List<Map<String, Object>> items) {
